	private static final IRI BUILD = SimpleValueFactory.getInstance().createIRI(NS + "smallBuild");
	private static final IRI PROBE = SimpleValueFactory.getInstance().createIRI(NS + "probe");
	private static final String QUERY = "SELECT ?n WHERE { ?s <" + BUILD + "> <" + YES + "> . ?s <" + PROBE
			+ "> ?n . FILTER(?n >= " + FIRST + ") }";

